fn auto_preserves_manually_changed_auto_masks_and_maximum_ids() {
    use lightcraft_develop::{Mask, MaskComponent, MaskOp, MaskShape};
    for (command, params) in [
        ("mask.adjust", json!({"id": 7, "values": {"exposure": 0.25}})),
